from collections import defaultdict, deque

def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=defaultdict(list)
 for r in range(h):
  for c in range(w):
   col=g[r][c]
   if (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); n=0
   while q:
    x,y=q.pop();n+=1
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<h and 0<=b<w and (a,b) not in seen and g[a][b]==col:
      seen.add((a,b));q.append((a,b))
   out[col].append(n)
 return {k: sorted(v,reverse=True) for k,v in out.items()}
for g in [g1,g2,gt]: print(comps(g))
